5: export default (
6:   keyword,
7:   filter,
8:   filterSort,
9:   filterMap,
10:   positions,
11:   setFilteredDevices,
12:   setFilteredPositions,
13: ) => {
14:   const groups = useSelector((state) => state.groups.items);
15:   const devices = useSelector((state) => state.devices.items);
16: 
17:   useEffect(() => {
18:     const deviceGroups = (device) => {
19:       const groupIds = [];
20:       let { groupId } = device;
21:       while (groupId) {
22:         groupIds.push(groupId);
23:         groupId = groups[groupId]?.groupId || 0;
24:       }
25:       return groupIds;
26:     };
27: 
28:     const filtered = Object.values(devices)
29:       .filter((device) => !filter.statuses.length || filter.statuses.includes(device.status))
30:       .filter(
31:         (device) =>
32:           !filter.groups.length || deviceGroups(device).some((id) => filter.groups.includes(id)),
33:       )
34:       .filter(
35:         (device) =>
36:           !filter.geofences.length ||
37:           (positions[device.id]?.geofenceIds || []).some((id) => filter.geofences.includes(id)),
38:       )
39:       .filter((device) => {
40:         const lowerCaseKeyword = keyword.toLowerCase();
41:         return [device.name, device.uniqueId, device.phone, device.model, device.contact].some(
42:           (s) => s && s.toLowerCase().includes(lowerCaseKeyword),
43:         );
44:       });
45:     switch (filterSort) {
46:       case 'name':
47:         filtered.sort((device1, device2) => device1.name.localeCompare(device2.name));
48:         break;
49:       case 'lastUpdate':
50:         filtered.sort((device1, device2) => {
51:           const time1 = device1.lastUpdate ? dayjs(device1.lastUpdate).valueOf() : 0;
52:           const time2 = device2.lastUpdate ? dayjs(device2.lastUpdate).valueOf() : 0;
53:           return time2 - time1;
54:         });
55:         break;
56:       default:
57:         break;
58:     }
59:     setFilteredDevices(filtered);
60:     setFilteredPositions(
61:       filterMap
62:         ? filtered.map((device) => positions[device.id]).filter(Boolean)
63:         : Object.values(positions),
64:     );
65:   }, [
66:     keyword,
67:     filter,
68:     filterSort,
69:     filterMap,
70:     groups,
71:     devices,
72:     positions,
73:     setFilteredDevices,
